sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
  try {
    var result;
    var __result = (function() {
      function ins(v){ var g=new GlideRecord('pa_indicators'); g.addQuery('name',v.name); g.query(); if(g.next()) return g.getUniqueValue(); g.initialize(); for(var k in v) g.setValue(k,v[k]); return g.insert(); }
      var base={type:'2',frequency:'10',aggregate:'2',unit:'a6a4d96097645f945c91b63de053affc',precision:'2',display:'true',value_when_nil:'0',forecast_periods:'2',forecast_base_periods:'2',scores_format:'kMGTPE'};
      function mk(e){var o={};for(var k in base)o[k]=base[k];for(var j in e)o[j]=e[j];return o;}
      var a=ins(mk({name:'DPM: Annual run cost ($M)',direction:'2',formula:'[[b11f09e497205f945c91b63de053af9b]] / 1000000',description:'Annual run cost in millions of dollars. Formula: DPM: Annual run cost divided by 1,000,000. Demo values are estimates allocated from the FY27 OST appropriation (Act 145).'}));
      var b=ins(mk({name:'DPM: Annual cost avoided ($M)',direction:'1',formula:'[[311f81e097245f945c91b63de053af7c]] / 1000000',description:'Annual cost avoided in millions of dollars. Formula: DPM: Annual cost avoided divided by 1,000,000. Demo values are estimates.'}));
      var bds=['b8f3f77e7770211051d2308eec5a99a6','f317ff3277b0211051d2308eec5a99d0','9b39d0837774211051d2308eec5a9925','998a9cc37774211051d2308eec5a993a'];
      [a,b].forEach(function(ind){ bds.forEach(function(bd){ var x=new GlideRecord('pa_indicator_breakdowns'); x.addQuery('indicator',ind); x.addQuery('breakdown',bd); x.query(); if(!x.next()){ x.initialize(); x.setValue('indicator',ind); x.setValue('breakdown',bd); x.insert(); } }); });
      throw new Error('IDS '+a+' '+b);
      ; if (typeof result !== 'undefined') return result;
    })();
    response.setBody({ success: true, result: (__result === undefined ? null : __result) });
  } catch(e) {
    response.setBody({ success: false, error: e + '', message: e.message || (e + '') });
  }
})(request, response);
